#[repr(u8)]
pub enum CropKind {
    Crop = 0,
    Tree = 1,
    Animal = 2,
}

/// What grows from a seed: a crop, tree or animal (`content/farming.toml`, docs/design/farming.md).
#[derive(Debug, PartialEq)]
