/// Whom a skill may be used on. The discriminant is the wire value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum SkillTarget {
    Enemy = 0,
    Ally = 1,
    Caster = 2,
}

/// What a skill's effect does. The discriminant is the wire value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum EffectKind {
    Damage = 0,
    Heal = 1,
    Status = 2,
    Cleanse = 3,
}

/// What a status does to movement and skills. The discriminant is the wire value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Control {
    None = 0,
    Stun = 1,
    Knockdown = 2,
    Snare = 3,
}

#[derive(Debug, PartialEq)]
pub struct EffectData {
    pub kind: EffectKind,
    /// Damage or healing; a status's per tick.
    pub amount: i32,
    /// A status effect's status wire, and how long it lasts.
    pub status: Option<u8>,
    pub ms: u32,
    /// The status the target must have for this effect to happen (a combo).
    pub when: Option<u8>,
}

/// Skillsets (`content/combat.toml`, docs/design/combat.md).
#[derive(Debug, PartialEq)]
pub struct SkillsetData {
    pub wire: u8,
    pub id: &'static str,
    /// What players see.
    pub name: &'static str,
    /// NPCs' skills: characters can't pick it, and its skills cost no mana.
    pub npc: bool,
}

