pub struct SkillData {
    /// Stored in casts and combat events.
    pub wire: u16,
    pub id: &'static str,
    /// What players see.
    pub name: &'static str,
    /// The skillset's wire.
    pub skillset: u8,
    /// The level a character must be to use it.
    pub level: u8,
    pub target: SkillTarget,
    /// 0 is instant.
    pub cast_ms: u32,
    pub cooldown_ms: u32,
    pub range_m: f32,
    pub cost_mp: i32,
    /// 0 lands at once; otherwise a projectile's speed, m/s.
    pub speed_mps: f32,
    /// The target must be in front.
    pub facing: bool,
    pub effects: &'static [EffectData],
}

