/// The status stored as `wire`.
pub fn status(wire: u8) -> Option<&'static StatusData> {
    STATUSES.get(usize::from(wire))
}

/// The status with content id `id`.
pub fn status_by_id(id: &str) -> Option<&'static StatusData> {
    STATUSES.iter().find(|d| d.id == id)
}

/// Levels, experience and skillset picks (`content/combat.toml`, docs/design/combat.md).
#[derive(Debug, PartialEq)]
pub struct ProgressRules {
    /// Experience from each level to the next; its length plus 1 is the level cap.
    pub xp_to_next: &'static [u32],
    /// The levels at which a skillset may be picked, one each.
    pub skillset_at: &'static [u8],
    /// What each level adds to the HP and mana maximums.
    pub hp_per_level: i32,
    pub mp_per_level: i32,
    /// Experience for a level-1 kill, more per victim level, less per level the killer is above it, in percent.
    pub kill_xp: u32,
    pub kill_xp_per_level: u32,
    pub kill_xp_gap_pct: u32,
    /// The share of a level's experience a death to anything but a character loses, in percent.
    pub death_xp_pct: u32,
}

pub static PROGRESS: ProgressRules = ProgressRules { xp_to_next: &[100, 150, 220, 300, 400, 520, 660, 820, 1000, 1200, 1450, 1750, 2100, 2500], skillset_at: &[1, 5, 10], hp_per_level: 100, mp_per_level: 40, kill_xp: 40, kill_xp_per_level: 20, kill_xp_gap_pct: 25, death_xp_pct: 5 };

/// Crowd control's diminishing returns (`content/combat.toml`, docs/design/combat.md).
#[derive(Debug, PartialEq)]
pub struct ControlRules {
    /// The window runs this long past the end of the last control that landed, s.
    pub window_s: u32,
    /// The share of its duration each control in a row lands for; past the last, immune.
    pub steps_pct: &'static [u32],
}

pub static CONTROL: ControlRules = ControlRules { window_s: 15, steps_pct: &[100, 50, 25] };

/// Evidence, reports and the attacker's mark (`[crime]` in `content/combat.toml`, docs/design/crime.md).
#[derive(Debug, PartialEq)]
pub struct CrimeRules {
    /// The wire of the status an attacker gets.
    pub mark: u8,
    /// How long the mark lasts, s.
    pub mark_s: i32,
    /// How long evidence lies before it fades, s.
    pub evidence_s: i32,
    /// How close a reporter must stand, horizontally and vertically, m.
    pub reach_m: f32,
    /// Crime points for reported Footprints.
    pub footprint_points: i32,
    /// Crime points for a reported Bloodstain.
    pub bloodstain_points: i32,
    /// Crime points for a reported Blood Pool.
    pub blood_pool_points: i32,
    /// Crime points at or above this make a character Sought.
    pub sought_points: i32,
}

pub static CRIME: CrimeRules = CrimeRules { mark: 10, mark_s: 30, evidence_s: 86400, reach_m: 4.0, footprint_points: 3, bloodstain_points: 1, blood_pool_points: 10, sought_points: 50 };

/// NPC rules (`content/npcs.toml`, docs/design/npcs.md).
#[derive(Debug, PartialEq)]
pub struct NpcRules {
    /// How often the brain thinks, ms: a multiple of the tick.
    pub brain_ms: i32,
    /// A spawn point with a living character this close has its NPC, m.
    pub wake_m: f32,
    /// An idle NPC with no character this close goes away, m.
    pub sleep_m: f32,
    /// This far from home an NPC gives up the fight, m.
    pub leash_m: f32,
    /// How often a moving NPC's position is published, ms.
    pub heartbeat_ms: i32,
    /// The shortest pause between strolls, s.
    pub wander_min_s: i32,
    /// The longest pause between strolls, s.
    pub wander_max_s: i32,
    /// A stroll's share of the kind's speed, in percent.
    pub walk_pct: i32,
    /// A return home's share of the kind's speed, in percent.
    pub return_pct: i32,
    /// How long a corpse lies, s.
    pub corpse_s: i32,
    /// When a corpse's loot is anyone's, s after the death.
    pub free_s: i32,
    /// The share of the damage the first hitter needs to own the loot, in percent.
    pub tag_pct: i32,
    /// Threat from healing someone an NPC fights, as a share of the HP healed, in percent.
    pub heal_threat_pct: i32,
    /// Threat from a debuff that deals no damage.
    pub status_threat: i32,
    /// How close a looter must stand, m.
    pub loot_m: f32,
}

pub static NPC: NpcRules = NpcRules { brain_ms: 200, wake_m: 120.0, sleep_m: 160.0, leash_m: 40.0, heartbeat_ms: 500, wander_min_s: 8, wander_max_s: 20, walk_pct: 45, return_pct: 150, corpse_s: 90, free_s: 30, tag_pct: 50, heal_threat_pct: 50, status_threat: 20, loot_m: 4.0 };

/// One line of a kind's loot: `min` to `max` of `item` with chance `pct`%.
#[derive(Debug, PartialEq)]
pub struct LootData {
    /// The item's wire.
    pub item: u16,
    pub min: u32,
    pub max: u32,
    pub pct: u32,
}

/// NPC kinds (`content/npcs.toml`, docs/design/npcs.md).
#[derive(Debug, PartialEq)]
pub struct NpcKindData {
    /// Stored in `entity.ref_id`.
    pub wire: u8,
    pub id: &'static str,
    /// What players see.
    pub name: &'static str,
    pub level: u8,
    pub hp: i32,
    pub speed_mps: f32,
    /// 0 attacks only when attacked.
    pub aggro_m: f32,
    pub wander_m: f32,
    pub respawn_s: u32,
    /// The placeholder body's height and colour (0xRRGGBB).
    pub size_m: f32,
    pub color: u32,
    /// Skill wires, tried in order.
    pub skills: &'static [u16],
    pub loot: &'static [LootData],
}

